import React, { ReactElement, useEffect, useMemo, useState } from \"react\";
import { Room } from \"matrix-js-sdk/src/models/room\";
import { RoomMember } from \"matrix-js-sdk/src/models/room-member\";
import { MatrixEvent } from \"matrix-js-sdk/src/models/event\";
import { logger } from \"matrix-js-sdk/src/logger\";

import { PillType } from \"../components/views/elements/PillType\";
import { ButtonEvent } from \"../components/views/elements/AccessibleButton\";
import RoomAvatar from \"../components/views/avatars/RoomAvatar\";
import MemberAvatar from \"../components/views/avatars/MemberAvatar\";
import { MatrixClientPeg } from \"../MatrixClientPeg\";
import { getPrimaryPermalinkEntity } from \"../utils/permalinks/Permalinks\";
import dis from \"../dispatcher/dispatcher\";
import { Action } from \"../dispatcher/actions\";

interface Args {
    room?: Room;
    type?: PillType;
    url?: string;
}

interface HookResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | \"space\" | null;
}

export function usePermalink({ room, type, url }: Args): HookResult {
    const resourceId = url ? getPrimaryPermalinkEntity(url) : null;
    const resolvedType = type ?? {
        \"@\": PillType.UserMention,
        \""'!": PillType.RoomMention,
        "#": PillType.RoomMention,
    }[resourceId?.[0]];
    const userId = resolvedType === PillType.UserMention && resourceId?.startsWith("@") ? resourceId : null;
    const roomId = resolvedType === PillType.RoomMention && resourceId && ["!", "#"].includes(resourceId[0])
        ? resourceId : null;
    const client = MatrixClientPeg.get();
    const localMember = userId ? room?.getMember(userId) : null;
    const [profile, setProfile] = useState<{ userId: string; displayname?: string; avatar_url?: string }>(null);

    useEffect(() => {
        setProfile(null);
        if (!userId || localMember) return;
        let cancelled = false;
        client.getProfileInfo(userId).then((response) => {
            if (!cancelled) setProfile({ userId, ...response });
        }).catch((err) => logger.error("Could not retrieve profile data for " + userId + ":", err));
        return () => { cancelled = true; };
    }, [client, userId, localMember]);

    const member = useMemo(() => {
        if (!userId) return null;
        if (localMember) return localMember;
        const fallback = new RoomMember(null, userId);
        if (profile?.userId === userId) {
            fallback.name = profile.displayname;
            fallback.rawDisplayName = profile.displayname;
            fallback.events.member = {
                getContent: () => ({ avatar_url: profile.avatar_url }),
                getDirectionalContent: () => ({ avatar_url: profile.avatar_url }),
            } as MatrixEvent;
        }
        return fallback;
    }, [userId, localMember, profile]);

    if (resolvedType === PillType.AtRoomMention) {
        return {
            type: resolvedType,
            resourceId: room?.roomId ?? null,
            text: "@room",
            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            onClick: null,
        };
    }
    if (userId) {
        return {
            type: resolvedType,
            resourceId: userId,
            text: member.rawDisplayName || userId,
            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
            onClick: (e: ButtonEvent): void => {
                e.preventDefault();
                dis.dispatch({ action: Action.ViewUser, member });
            },
        };
    }
    if (roomId) {
        const resolvedRoom = roomId[0] === "#"
            ? client.getRooms().find((r) => r.getCanonicalAlias() === roomId || r.getAltAliases().includes(roomId))
            : client.getRoom(roomId);
        return {
            type: resolvedRoom?.isSpaceRoom() ? "space" : resolvedType,
            resourceId: resolvedRoom?.roomId ?? roomId,
            text: resolvedRoom?.name || roomId,
            avatar: resolvedRoom ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null,
            onClick: null,
        };
    }
    return { type: null, resourceId: null, text: null, avatar: null, onClick: null };
}
EOF'

