import React from \"react\";
import { render } from \"@testing-library/react\";
import { Room } from \"matrix-js-sdk/src/models/room\";

import { Pill, PillType, pillRoomNotifLen, pillRoomNotifPos } from \"../../../../src/components/views/elements/Pill\";
import { MatrixClientPeg } from \"../../../../src/MatrixClientPeg\";
import { stubClient } from \"../../../test-utils\";

describe(\"Pill\", () => {
    beforeEach(() => stubClient());

    it(\"renders nothing for an unrecognized link\", () => {
        const { container } = render(<Pill url=\"https://example.org/page\" inMessage />);
        expect(container.firstChild).toBeNull();
    });

    it(\"keeps the supplied room permalink and DOM structure in a message\", () => {
        const client = MatrixClientPeg.get();
        const room = new Room(\""'!room:id", client, client.getUserId());
        (client.getRoom as jest.Mock).mockReturnValue(room);
        const url = "https://matrix.to/#/!room:id?via=example.org";
        const { container } = render(<Pill url={url} inMessage />);
        const wrapper = container.querySelector("bdi");
        const link = wrapper?.querySelector("a.mx_Pill.mx_RoomPill");
        expect(link?.getAttribute("href")).toBe(url);
        expect(link?.querySelector(".mx_Pill_linkText")?.textContent).toBe(room.name);
    });

    it("renders a non-navigating @room pill and finds its token", () => {
        const { container } = render(<Pill type={PillType.AtRoomMention} inMessage />);
        expect(container.querySelector("bdi > span.mx_Pill.mx_AtRoomPill .mx_Pill_linkText")?.textContent).toBe("@room");
        expect(container.querySelector("a")).toBeNull();
        expect(pillRoomNotifPos("hello @room @room")).toBe(6);
        expect(pillRoomNotifLen()).toBe(5);
    });
});
